import{_ as a,o,c as t,a3 as r}from"./chunks/framework.CWSmAuPU.js";const g=JSON.parse('{"title":"0016 一键升级：从 git 标签下载到 versions/ 再切换","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0016-upgrade-from-tags.md","filePath":"reference/adr/0016-upgrade-from-tags.md","lastUpdated":null}'),d={name:"reference/adr/0016-upgrade-from-tags.md"};function i(s,e,l,c,n,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_0016-一键升级-从-git-标签下载到-versions-再切换" tabindex="-1">0016 一键升级：从 git 标签下载到 versions/ 再切换 <a class="header-anchor" href="#_0016-一键升级-从-git-标签下载到-versions-再切换" aria-label="Permalink to &quot;0016 一键升级：从 git 标签下载到 versions/ 再切换&quot;">​</a></h1><ul><li>状态：已采纳（在 <a href="./0009-versioned-install-layout">0009</a> 的目录结构上增加自动化）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>手工升级要 clone、npm install、运行 install.mjs 三步，非专业开发的使用者容易漏掉 npm install 或在错误的目录运行。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><code>node install.mjs --upgrade [版本]</code>（<code>req upgrade</code>）：用 <code>git ls-remote --tags</code> 读取已发布版本，<code>git clone --depth 1 --branch &lt;标签&gt;</code> 到 <code>versions/&lt;版本&gt;</code>，<code>npm install --omit=dev</code>，再运行新版本的 <code>install.mjs</code> 切换。</li><li>不写版本时取最新版本；当前是正式版时只升级到正式版，当前是预发布版（beta）时也考虑预发布版。</li><li>下载地址取 <code>package.json</code> 的 <code>repository</code>，可用环境变量 <code>REQ_KIT_REPO_URL</code> 或 <code>--from</code> 改为内网镜像。</li><li>任何一步失败，当前版本不受影响；下载先写到临时目录，完整后才改名为版本目录。</li><li>安装时在 <code>~/.req-kit/bin</code> 写入 <code>req</code>（和 Windows 的 <code>req.cmd</code>），指向当前启用的版本。是否加入 PATH 由使用者决定，安装程序只给出命令，不修改系统设置。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>升级只需要 git 和 npm 可用；回滚仍是在旧版本目录运行 <code>node install.mjs</code>。体检会提示有新版本（离线时跳过）。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0016-upgrade-from-tags.md">docs/adr/0016-upgrade-from-tags.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0016-upgrade-from-tags.md">在 GitHub 上编辑</a></p>',2)])])}const h=a(d,[["render",i]]);export{g as __pageData,h as default};
